import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import {createSurfaceSession} from '../src/index.ts';
import {config,proposal,raw} from './fixture.ts';
function rejects(p: any, code?: string) {const s=createSurfaceSession(config());const r=s.submit(typeof p==='string'?p:JSON.stringify(p));assert.equal(r.ok,false);if(code)assert.equal(r.code,code);assert.equal(s.getSnapshot().revision,0)}
test('v1 admits frozen complete snapshot with host provenance',()=>{const s=createSurfaceSession(config());assert.equal(s.submit(raw()).ok,true);const r=s.getSnapshot();assert.equal(r.revision,1);assert.equal(r.provenance.sourceLabel,'Offline skill preview');assert.equal(Object.isFrozen(r.proposal?.components[0].props),true)});
for(const [field,value] of [['schema','cue.command-mesh.surface/v2'],['catalogVersion','a2ui/0.9.1'],['trusted',true],['approved',true],['data',{secret:'no'}]])test(`rejects boundary ${field}`,()=>rejects(proposal({[field as string]:value})));
test('rejects unregistered or unknown components and extra style/HTML fields',()=>{for(const type of ['Html','Script','IFrame','ApprovalDialog']){const p=proposal();p.components[1].type=type;rejects(p)}for(const field of ['html','style','onClick','fetch','approved']){const p=proposal();p.components[1].props[field]='javascript:alert(1)';rejects(p)}const s=createSurfaceSession(config({registeredComponents:new Set(['Group','Text','Metric'])}));assert.equal(s.submit(raw()).ok,false)});
test('dangerous strings are data, never executable markup',()=>{const p=proposal();p.components[1].props.text='<script>alert(1)</script><img src=x onerror=fetch("x")> javascript:evil()';assert.equal(createSurfaceSession(config()).submit(JSON.stringify(p)).ok,true)});
test('rejects unknown actions and write-kind host configuration',()=>{const p=proposal();p.components[1].actionRef='delete';rejects(p);assert.throws(()=>createSurfaceSession(config({actions:new Map([['inspect',{kind:'execute',label:'Delete',target:{view:'tasks'}}]])})),/action/i)});
test('denies prototype keys, path traversal, dotted and URL dataRefs',()=>{for(const ref of ['__proto__','constructor','prototype','count.value','../secrets','https://evil.test','/count']){const p=proposal();p.components[2].dataRef=ref;rejects(p)}rejects(raw().replace('"text":"Agent proposal"','"__proto__":{},"text":"safe"'));assert.equal(({} as any).polluted,undefined)});
test('rejects duplicate JSON keys including escaped equivalents',()=>{rejects(raw().replace('"rootId":"root"','"rootId":"bad","rootId":"root"'),'duplicate-key');rejects(raw().replace('"rootId":"root"','"rootId":"bad","root\\u0049d":"root"'),'duplicate-key')});
test('rejects duplicate ids cycles dangling children multiple parents unreachable nodes',()=>{let p=proposal();p.components[2].id='greeting';rejects(p);p=proposal();p.components[0].children.push('root');rejects(p);p=proposal();p.components[0].children.push('missing');rejects(p);p=proposal();p.components[0].children.push('count');rejects(p);p=proposal();p.components[0].children=['greeting'];rejects(p)});
test('rejects graph depth, byte, text and component budgets',()=>{const p=proposal();p.components=[...Array.from({length:13},(_,i)=>({id:'n'+i,type:'Group',props:{layout:'stack'},children:[i===12?'leaf':'n'+(i+1)]})),{id:'leaf',type:'Text',props:{text:'x'}}];p.rootId='n0';rejects(p);rejects(' '.repeat(262145),'size');const q=proposal();q.components[1].props.text='🫠'.repeat(3000);rejects(q);const s=createSurfaceSession(config({limits:{maxComponents:2,minUpdateIntervalMs:0}}));assert.equal(s.submit(raw()).ok,false);rejects('['.repeat(40)+']'.repeat(40),'json-depth')});
test('rejects non-JSON numbers and non-JSON raw input',()=>{rejects(raw().replace('"baseRevision":0','"baseRevision":1e400'));assert.equal(createSurfaceSession(config()).submit({} as any).ok,false)});
test('rejection is atomic and session, surface and baseRevision are enforced',()=>{const s=createSurfaceSession(config());s.submit(raw());const held=s.getSnapshot().proposal;assert.equal(s.submit(raw()).ok,false);assert.equal(s.getSnapshot().proposal,held);assert.equal(s.getSnapshot().revision,1);assert.ok(s.getSnapshot().error);for(const p of [proposal({baseRevision:1,sessionId:'other'}),proposal({baseRevision:1,surfaceId:'other'})])assert.equal(s.submit(JSON.stringify(p)).ok,false);assert.equal(s.submit(raw({baseRevision:1})).ok,true);assert.equal(s.getSnapshot().error,null)});
test('layout updates keep component ids and focus target must be immediate child',()=>{const s=createSurfaceSession(config());s.submit(raw());const p=proposal({baseRevision:1});p.components[0].props={layout:'focus',focusId:'count'};assert.equal(s.submit(JSON.stringify(p)).ok,true);p.baseRevision=2;p.components[0].props.focusId='nope';assert.equal(s.submit(JSON.stringify(p)).ok,false)});
test('snapshot and registry mutation cannot change admitted action',()=>{const c=config(),s=createSurfaceSession(c);s.submit(raw());c.actions.get('inspect').target.view='secrets';c.actions.clear();const i=s.getIntent('greeting',1);assert.equal(i?.kind,'navigate');assert.deepEqual(i?.target,{view:'tasks'});assert.equal(Object.isFrozen(i),true)});
test('intent requires admitted component, revision and one explicit activation per revision',()=>{const s=createSurfaceSession(config());assert.equal(s.getIntent('greeting',0),null);s.submit(raw());assert.equal(s.getIntent('count',1),null);assert.equal(s.getIntent('greeting',0),null);assert.equal(s.getIntent('greeting',1)?.surfaceRevision,1);assert.equal(s.getIntent('greeting',1),null);s.submit(raw({baseRevision:1}));assert.equal(s.getIntent('greeting',2)?.surfaceRevision,2)});
test('rate limiting and subscriptions are deterministic and bounded',()=>{let now=0;const s=createSurfaceSession(config({now:()=>now,limits:{minUpdateIntervalMs:50}}));let n=0;const off=s.subscribe(()=>n++);assert.equal(s.submit(raw()).ok,true);assert.equal(s.submit(raw({baseRevision:1})).code,'rate-limit');now=51;assert.equal(s.submit(raw({baseRevision:1})).ok,true);off();now=102;s.submit(raw({baseRevision:2}));assert.equal(n,3)});
test('exported schema is closed and declares every built-in component',()=>{const schema=JSON.parse(readFileSync(new URL('../schema/surface-v1.schema.json',import.meta.url),'utf8'));assert.equal(schema.additionalProperties,false);assert.equal(schema.properties.schema.const,'cue.command-mesh.surface/v1');assert.equal(schema.$defs.component.oneOf.length,9)});
test('repeated rejected floods notify once per error rather than rerender for every packet',()=>{const s=createSurfaceSession(config({now:()=>0,limits:{minUpdateIntervalMs:50}}));s.submit(raw());let count=0;s.subscribe(()=>count++);for(let i=0;i<100;i++)s.submit(raw({baseRevision:1}));assert.equal(count,1)});
test('rejects lone Unicode surrogates, trailing garbage and malformed JSON',()=>{for(const text of ['"\\ud800"','"\\udc00"','{}x','{"a":1,}','[1,]','{"a":NaN}','{"a":undefined}'])rejects(text)});
test('registry changes and invalid host limits cannot broaden admission',()=>{const c=config(),s=createSurfaceSession(c);c.registeredComponents.delete('Text');assert.equal(s.submit(raw()).ok,true);for(const limits of [{maxBytes:999999999},{maxDepth:0},{maxRows:-1},{maxJsonDepth:100},{unknown:2}])assert.throws(()=>createSurfaceSession(config({limits})),/limits/)});
test('host intent cannot carry arbitrary URLs or methods even through trusted registry',()=>{for(const target of [{view:'https://evil.test'},{view:'tasks',url:'https://evil.test'},{view:'tasks',execute:true}])assert.throws(()=>createSurfaceSession(config({actions:new Map([['inspect',{kind:'navigate',label:'go',target}]])})),/action/)});
test('suggestion intents are distinct from navigation and contain no approval or execution',()=>{const s=createSurfaceSession(config({actions:new Map([['inspect',{kind:'suggest',label:'Prüfen',target:{topic:'review-skill',entityId:'skill1'}}]])}));s.submit(raw());const i=s.getIntent('greeting',1);assert.equal(i?.kind,'suggest');assert.deepEqual(i?.target,{topic:'review-skill',entityId:'skill1'});assert.equal('approved' in i!,false);assert.equal('execute' in i!,false)});
